"""Luxury visual system and editorial pages; loaded by build.py."""
ART=json.loads((R/'articles.json').read_text());ARTMAP={a['slug']:a for a in ART}
CAT=json.loads((R/'prototype-catalog.json').read_text())
SOURCES=json.loads((R/'editorial-image-sources.json').read_text())
def money(n):return f'{n:,}'.replace(',','.')+'đ'
def asset(name,alt='',cls='',eager=False):
 return f'<img class="{cls}" src="{base}assets/{name}.webp" alt="{e(alt)}" {"fetchpriority=high" if eager else "loading=lazy"} decoding="async">'
def brandlogo():return asset('logo','Đỗ Thị Tuyết — Sâm Nữ Hoàng','brand-logo')
def assumption():return '<p class="prototype-label">GIÁ & QUY CÁCH GIẢ ĐỊNH ĐỂ DUYỆT</p>'
def picker(key):
 c=CAT[key]
 return f'''<div class="purchase" data-product="{key}">{assumption()}<div class="price-line"><strong class="variant-price">{money(c['variants'][0]['price'])}</strong><span>/ quy cách</span></div><label class="field-label" for="variant-{key}">Chọn quy cách</label><select id="variant-{key}" class="variant-select">{''.join(f'<option value="{i}" data-price="{v["price"]}">{v["label"]} — {money(v["price"])}</option>' for i,v in enumerate(c['variants']))}</select><div class="quantity-line"><label for="qty-{key}">Số lượng</label><div class="stepper"><button type="button" data-step="-1" aria-label="Giảm số lượng">−</button><input class="quantity" id="qty-{key}" type="number" min="1" max="99" value="1" inputmode="numeric"><button type="button" data-step="1" aria-label="Tăng số lượng">＋</button></div><strong class="line-total">{money(c['variants'][0]['price'])}</strong></div><button class="button cart-add" type="button">Thêm vào dự toán ＋</button><p class="fine">Bản duyệt · Chưa phải báo giá chính thức. Danh sách được lưu trên thiết bị, chưa gửi đơn hàng.</p></div>'''
def winecard(w):
 c=CAT[w['slug']];v=c['variants'][0]
 return f'''<article class="wine-card reveal" data-wine="{w['slug']}" data-search="{e(w['name'])}"><a class="wine-image studio {c['asset']}" href="{href('san-pham/ruou-sam/'+w['slug'])}">{asset(c['asset'],w['name'])}<span class="image-arrow">↗</span></a><div class="card-meta"><span>{w['label']}</span><span>{v['label']}</span></div><h3>{link('san-pham/ruou-sam/'+w['slug'],w['name'])}</h3><div class="card-bottom"><span>Từ <b>{money(v['price'])}</b></span>{link('san-pham/ruou-sam/'+w['slug'],'Khám phá ↗','underlink')}</div><small class="price-note">Giá & dung tích giả định để duyệt</small></article>'''
def categorycard(p):
 key=p['slug'];a='bottle' if key=='ruou-sam' else CAT[key]['asset']
 return f'''<article class="category-card reveal"><a class="category-image studio" href="{href('san-pham/'+key)}">{asset(a,p['short'])}<span class="category-number">{p['number']}</span></a><p class="eyebrow">{p['label']}</p><h3>{link('san-pham/'+key,p['short'])}</h3><p>{p['desc']}</p>{link('san-pham/'+key,'Khám phá dòng sản phẩm ↗','underlink')}</article>'''
def articlecard(a):
 return f'''<article class="journal-card reveal" data-topic="{a['tag']}"><a class="journal-image" href="{href('kien-thuc/'+a['slug'])}">{asset(a['image'],a['title'])}</a><p class="eyebrow">{a['tag']}</p><h3>{link('kien-thuc/'+a['slug'],a['title'])}</h3><p>{a['intro']}</p>{link('kien-thuc/'+a['slug'],'Đọc câu chuyện ↗','underlink')}</article>'''
def home():
 return f'''<section class="royal-hero"><div class="royal-copy"><p class="eyebrow">ĐỖ THỊ TUYẾT · SÂM NỮ HOÀNG</p><span class="fine-rule"></span><h1>Ngự Vị<br><em>Nữ Hoàng Tưu</em></h1><p class="hero-description">Một món quà được chọn bằng sự trân trọng.<br>Một dấu ấn từ sắc gỗ, dáng bình và sắc rượu.</p><div class="hero-actions">{link('san-pham/ruou-sam','Khám phá bộ sưu tập ↗','button gold')}{link('gioi-thieu','Câu chuyện thương hiệu','underlink')}</div><div class="hero-signature"><span>01 — 05</span><p>GỖ SỒI · THỦY TINH · HỒ LÔ</p></div></div><div class="royal-stage"><span class="stage-halo"></span><span class="stage-word">NGỰ VỊ</span>{asset('oak','Trống rượu gỗ sồi Ngự Vị Nữ Hoàng Tưu','hero-oak',True)}{asset('bottle','Chai Ngự Vị Nữ Hoàng Tưu','hero-bottle',True)}<div class="stage-plinth"></div><p class="stage-caption">BỘ SƯU TẬP NGỰ VỊ NỮ HOÀNG TƯU</p></div><a href="#bo-suu-tap" class="scroll-cue">KHÁM PHÁ ↓</a></section>
<div class="collection-strip"><div class="container"><span>THE COLLECTION</span>{''.join(link('san-pham/ruou-sam/'+w['slug'],w['name']) for w in W)}</div></div>
<section class="container section" id="bo-suu-tap">{heading('BỘ SƯU TẬP ĐẶC TRƯNG','Dáng vẻ tinh tế.<br><em>Dấu ấn riêng biệt.</em>','Năm cách thể hiện của Ngự Vị Nữ Hoàng Tưu. Chọn một kiểu dáng để xem ảnh, quy cách và giá dự kiến.',link('san-pham/ruou-sam','Tất cả sản phẩm ↗','underlink'))}<div class="wine-grid home-wines">{''.join(winecard(w) for w in W[:3])}</div><div class="collection-last">{''.join(winecard(w) for w in W[3:])}<div class="collection-quote"><span>“</span><h3>Sự trân trọng<br>nằm trong<br><em>từng lựa chọn.</em></h3><p>Khám phá chai quà tặng và bình hồ lô.</p></div></div></section>
<section class="signature-section"><div class="container signature-layout"><div class="signature-art studio">{asset('gourd','Bình hồ lô Ngự Vị Nữ Hoàng Tưu')}</div><div class="signature-copy reveal"><p class="eyebrow">NGHỆ THUẬT CHỌN QUÀ</p><h2>Dành cho<br><em>những dịp đáng nhớ.</em></h2><p>Một món quà phù hợp bắt đầu từ người nhận. Dáng chai thanh lịch, bình hồ lô tròn đầy hay trống gỗ sồi nổi bật — mỗi lựa chọn mang một cách bày tỏ riêng.</p>{link('kien-thuc/chon-quy-cach-ngu-vi','Cẩm nang chọn quy cách ↗','button outline')}<span class="signature-line">Ngự Vị Nữ Hoàng Tưu</span></div></div></section>
<section class="container section">{heading('BỐN DÒNG SẢN PHẨM','Từ nguyên liệu.<br><em>Đến món quà thành ý.</em>','Sâm tươi, sâm khô, cao sâm và bộ sưu tập rượu.')}<div class="category-grid">{''.join(categorycard(p) for p in P)}</div><p class="fine">Ảnh nguyên liệu được dựng từ tư liệu có nguồn; bao bì cao sâm là thiết kế minh họa. Xem chú thích tại trang sản phẩm.</p></section>
<section class="brand-story"><div class="container story-layout"><div class="story-brand">{brandlogo()}<span>HÀ NỘI · VIỆT NAM</span></div><div class="story-copy reveal"><p class="eyebrow">CÂU CHUYỆN ĐỖ THỊ TUYẾT</p><h2>Gắn bó với đất.<br><em>Chăm chút từng sản phẩm.</em></h2><p>Hộ kinh doanh cá thể Đỗ Thị Tuyết phát triển Sâm Nữ Hoàng từ hai vùng trồng tại Hà Nội. Theo thông tin chủ hộ, cây giống được nhập và trồng với sự cho phép của MS Thiên Ngọc.</p><div class="story-facts"><div><strong>3<span> ha</span></strong><small>TỔNG DIỆN TÍCH</small></div><div><strong>2<span> ha</span></strong><small>SÓC SƠN</small></div><div><strong>1<span> ha</span></strong><small>ỨNG HÒA</small></div></div>{link('gioi-thieu','Tìm hiểu thương hiệu ↗','underlink')}</div></div></section>
<section class="container section">{heading('TẠP CHÍ SÂM NỮ HOÀNG','Hiểu nguồn gốc.<br><em>Trân trọng giá trị.</em>','Những bài đọc về giống cây, người nghiên cứu và cách lựa chọn sản phẩm.',link('kien-thuc','Đọc tất cả bài viết ↗','underlink'))}<div class="journal-grid">{''.join(articlecard(a) for a in ART[:3])}</div></section>{cta()}'''
old_wine_detail=wine_detail

def wine_detail(w):
 key=w['slug'];c=CAT[key];ims=w['images']
 gallery=f'<div class="product-gallery"><button class="main-photo studio" data-image="{base}assets/{c["asset"]}.webp" data-caption="{e(w["name"])} — ảnh xử lý nền" aria-label="Phóng to ảnh">{asset(c["asset"],w["name"],eager=True)}<span>Phóng to ＋</span></button><div class="gallery-thumbnails"><button data-thumbnail="{base}assets/{c["asset"]}.webp" data-caption="{w["name"]} — ảnh xử lý nền" aria-label="Ảnh trình bày" aria-pressed="true" class="selected">{asset(c["asset"],w["name"])}</button>'+''.join(f'<button data-thumbnail="{base}assets/photo-{i:02d}.webp" data-caption="{e(w["name"])} — ảnh gốc {n+1}" aria-label="Xem ảnh gốc {n+1}" aria-pressed="false">{pic(i,w["name"])}</button>' for n,i in enumerate(ims))+ '</div><p class="fine">Ảnh chính đã xử lý nền bằng AI; các ảnh gốc được giữ để đối chiếu bao bì. Thông tin trên nhãn cần đọc từ ảnh gốc.</p></div>'
 return f'<div class="container">{crumb([("san-pham","Sản phẩm"),("san-pham/ruou-sam","Rượu sâm"),(None,w["name"])])}</div><section class="container product-detail">{gallery}<div class="product-info"><p class="eyebrow">NGỰ VỊ NỮ HOÀNG TƯU</p><h1>{w["name"]}</h1><p class="lead">{w["desc"]}</p><div class="trait-list">'+''.join(f'<span>{e(t)}</span>' for t in w['features'])+'</div>'+picker(key)+table([('Nồng độ mẫu',c['abv']+' · giả định'),('Bao bì',w['name']),('Tư vấn',call('0972 686 765','underlink'))])+f'<p class="alcohol-note">Dành cho người từ 18 tuổi. Không uống rượu bia khi lái xe.</p></div></section><section class="container section"><div class="detail-tabs"><a href="#dac-diem">Đặc điểm</a><a href="#quy-cach">Quy cách</a><a href="#goi-y">Cẩm nang</a></div><div class="detail-reading" id="dac-diem"><h2>Vẻ đẹp trong từng chi tiết.</h2><p>{w["desc"]}</p><p>Hình ảnh giúp quan sát kiểu bao bì và cách trưng bày. Màu rượu trong ảnh có thể thay đổi theo ánh sáng. Thành phần và thông số của từng lô sẽ được cập nhật từ hồ sơ sản phẩm.</p></div><div class="detail-reading" id="quy-cach"><h2>Quy cách & giá dự kiến.</h2>{assumption()}'+table([(v['label'],money(v['price'])) for v in c['variants']])+f'<p>Các con số trên phục vụ bản thiết kế để chủ hộ duyệt; chưa xác nhận dung tích, nồng độ hoặc giá bán thực tế.</p></div><div id="goi-y">{heading("CẨM NANG","Chọn một món quà phù hợp.")}<div class="journal-grid">{articlecard(ARTMAP["chon-quy-cach-ngu-vi"])}{articlecard(ARTMAP["trong-ruou-go-soi"])}</div></div></section><section class="container section">{heading("CÙNG BỘ SƯU TẬP","Những lựa chọn khác.")}<div class="wine-grid related-grid">'+''.join(winecard(x) for x in W if x['slug']!=key)+'</div></section>'
def generic_product(p):
 key=p['slug'];c=CAT[key]
 info={'sam-tuoi':('Củ tươi · nguyên liệu','Ảnh minh họa được xử lý từ ảnh củ sâm trong bài Báo Nông nghiệp và Môi trường (NVCC). Không phải ảnh lô hàng Đỗ Thị Tuyết.','https://nongnghiepmoitruong.vn/sam-nu-hoang-tiem-nang-moi-cua-nganh-duoc-d760090.html','Củ tươi có các lựa chọn khối lượng để trao đổi theo nhu cầu. Thời điểm thu hoạch, tình trạng làm sạch và giao nhận sẽ được xác nhận theo từng lô.'),'sam-kho':('Củ cắt lát · quy cách dự kiến','Ảnh dựng từ tư liệu củ cắt lát của HTV / Kiều Nhi; minh họa hình dạng nguyên liệu, chưa phải ảnh thành phẩm sâm khô.','https://htv.vn/ms-thien-ngoc-tu-nghien-cuu-cay-duoc-lieu-quy-ms-nu-hoang-222260911102637333.htm','Quy cách cắt lát được đưa vào bản duyệt với ba mức khối lượng. Phương pháp sấy, độ ẩm và thời hạn bảo quản cần cập nhật từ hồ sơ của sản phẩm thực tế.'),'cao-sam':('Hũ cao · hộp quà dự kiến','Thiết kế bao bì minh họa bằng AI. Giá 100g tham khảo sản phẩm của Sâm Nữ Hoàng Việt Nam; đây chưa phải bao bì hoặc công thức của Đỗ Thị Tuyết.','https://samnuhoangvietnam.com/san-pham/cao-sam-nu-hoang-205','Dòng cao cô đặc được xây dựng với hũ thủy tinh và hộp quà. Thành phần, bộ phận cây dùng để nấu cao và hướng dẫn sử dụng sẽ được xác nhận riêng; không lấy công thức của đơn vị tham khảo làm công thức của hộ kinh doanh.')}
 label,cap,url,desc=info[key]
 return f'<div class="container">{crumb([("san-pham","Sản phẩm"),(None,p["short"])])}</div><section class="container product-detail"><div><div class="main-photo studio ingredient-photo">{asset(c["asset"],p["short"]+" — ảnh minh họa",eager=True)}</div><p class="fine photo-credit">{cap} <a href="{url}" target="_blank" rel="noopener noreferrer">Xem nguồn tham khảo ↗</a></p></div><div class="product-info"><p class="eyebrow">{label}</p><h1>{p["name"]}</h1><p class="lead">{p["desc"]}</p>{picker(key)}<p>{desc}</p>{call("Trao đổi cùng Đỗ Thị Tuyết ↗","underlink")}</div></section><section class="container section">{heading("HIỂU ĐÚNG SẢN PHẨM","Từ nguyên liệu đến lựa chọn.")}<div class="journal-grid">{articlecard(ARTMAP["sam-tuoi-sam-kho-cao-sam"])}{articlecard(ARTMAP["doc-hieu-thanh-phan-sam"])}</div></section>{cta()}'
def bibliography():
 rows=json.loads((R/'source-index.json').read_text())
 return '<details class="bibliography"><summary>Tra cứu toàn bộ '+str(len(rows))+' mục từ danh_muc_bai_viet.csv</summary><div class="bibliography-list">'+''.join(f'<a href="{e(x["source_url"])}" target="_blank" rel="noopener noreferrer"><span>{e(x["publisher"] or "Nguồn công khai")}</span><strong>{e(x["title"] or x["source_url"])}</strong><small>{"Đã có bản tải" if x["status"]=="downloaded" else "Chỉ có đường dẫn nguồn"} ↗</small></a>' for x in rows)+'</div></details>'
def journal():
 return title('TẠP CHÍ SÂM NỮ HOÀNG','Nguồn gốc rõ ràng.<br><em>Câu chuyện có chiều sâu.</em>','Từ người nghiên cứu giống cây, tư liệu vùng trồng đến cách đọc thành phần và lựa chọn quy cách.')+f'<section class="container"><label class="journal-search" for="article-search">Tìm bài viết<input id="article-search" type="search" placeholder="Giống sâm, Võ Thị Ngọc, thành phần, gỗ sồi…"></label><p id="article-status" class="fine" aria-live="polite">{len(ART)} bài biên soạn</p><div class="journal-grid searchable-journal">'+''.join(articlecard(a) for a in ART)+f'</div><p id="article-empty" hidden>Chưa tìm thấy bài phù hợp. Thử từ khóa khác.</p></section><section class="container section">{heading("THƯ MỤC TƯ LIỆU","Các nguồn đọc thêm.")}<p>Bài biên soạn có dẫn nguồn và liên kết nội bộ. Tư liệu báo chí và ảnh ngoài đơn vị được chú thích, không thay thế hồ sơ chất lượng sản phẩm.</p><div class="source-grid">{sourcecards()}</div>{bibliography()}</section>'
def article(a):
 toc=''.join(f'<a href="#muc-{i}"><span>0{i+1}</span>{e(h)}</a>' for i,(h,p) in enumerate(a['sections']))
 refs=''.join(f'<li><a href="{e(x["url"])}" target="_blank" rel="noopener noreferrer">{e(x["name"])} ↗</a></li>' for x in a['sources']) or '<li>Ảnh sản phẩm và thông tin hộ kinh doanh do chủ hộ cung cấp. Nội dung hướng dẫn được biên soạn cho bộ sưu tập.</li>'
 return f'<div class="container">{crumb([("kien-thuc","Kiến thức"),(None,a["title"])])}</div><section class="article-heading container"><p class="eyebrow">{a["tag"]}</p><h1>{a["title"]}</h1><p class="lead">{a["intro"]}</p><p class="article-byline">Biên soạn: Sâm Nữ Hoàng · {a["date"]} · 3 phút đọc</p></section><figure class="article-cover container">{asset(a["image"],a["caption"])}<figcaption>{a["caption"]}</figcaption></figure><section class="container article-layout"><aside class="article-toc"><p class="eyebrow">TRONG BÀI VIẾT</p>{toc}<a href="#nguon">Nguồn tham khảo ↗</a></aside><div class="article-body">'+''.join(f'<section id="muc-{i}"><h2>{e(h)}</h2><p>{e(p)}</p></section>' for i,(h,p) in enumerate(a['sections']))+f'<section id="nguon" class="article-sources"><h2>Nguồn tham khảo</h2><ul>{refs}</ul></section><div class="article-next"><p class="eyebrow">KHÁM PHÁ THÊM</p>{link("san-pham","Bốn dòng sản phẩm Sâm Nữ Hoàng ↗","underlink")}<br>{link("vung-trong","Vùng trồng Đỗ Thị Tuyết tại Hà Nội ↗","underlink")}</div></div></section><section class="container section">{heading("ĐỌC TIẾP","Những câu chuyện liên quan.")}<div class="journal-grid">'+''.join(articlecard(ARTMAP[k]) for k in a['related'])+'</div></section>'
old_content=content
old_about=about
def about():
 out=old_about();out=out.replace(f'<div class="business-seal reveal">{mark}<span>SÂM NỮ HOÀNG</span><small>HỘ KINH DOANH CÁ THỂ<br>ĐỖ THỊ TUYẾT</small></div>',f'<div class="business-seal reveal">{brandlogo()}</div>')
 return out.replace('Các dòng sâm tươi, sâm khô và cao sâm sẽ tiếp tục được bổ sung thông tin chi tiết.','Theo thông tin chủ hộ, doanh nghiệp nhập giống và trồng theo sự cho phép của MS Thiên Ngọc, gắn với bà Võ Thị Ngọc. Các bài tư liệu có nguồn được giới thiệu tại chuyên mục Kiến thức.')
def content(s):
 if s=='kien-thuc':return journal()
 if s.startswith('kien-thuc/'):return article(ARTMAP[s.split('/')[-1]])
 if s=='thuong-hieu':return title('NHẬN DIỆN THƯƠNG HIỆU','Đỗ Thị Tuyết.<br><em>Sâm Nữ Hoàng.</em>','Biểu trưng kết hợp chữ cái ĐT, vương miện lá và bộ rễ — gắn người gây dựng thương hiệu với cây sâm.')+f'<section class="container brand-download"><div class="logo-sheet">{brandlogo()}</div><div><h2>Sắc vàng champagne.<br>Nền bordeaux.</h2><p>Logo đề xuất cho hệ thống nhận diện: bao bì, website và ấn phẩm. Bản hiện tại là PNG nền trong suốt; bản vector sản xuất cần được dựng lại sau khi duyệt mẫu.</p><a class="button" href="{base}assets/logo-original.png" download="logo-do-thi-tuyet-sam-nu-hoang.png">Tải logo PNG nền trong ↓</a></div></section>'
 out=old_content(s)
 if s=='lien-he':out=out.replace('<section class="container contact-layout">','<section class="container section estimate-section"><p class="eyebrow">DANH SÁCH DỰ TOÁN</p><h2>Lựa chọn của bạn.</h2><div id="cart-items"></div><div class="cart-total"></div><button id="download-cart" class="button">Tải dự toán ↓</button><p class="fine">Giá và thông số giả định để duyệt. Dữ liệu chỉ lưu trên thiết bị, chưa gửi đơn hàng.</p></section><section class="container contact-layout">')
 return out
